// A year of weather as one chart, in the manner of a newspaper's annual
// weather page: every day of the past twelve months as a bar from its low to
// its high, colored by how warm the day was, the week ahead in pale after
// today, the warmest and coldest days marked, and the rain month by month
// underneath.
import { celsius, temperatureColor, MONTHS, degrees } from './weather'

const PAPER = '#f6f3ee'
const INK = '#26221d'
const SOFT = '#7d756b'
const GRID = '#e2dcd2'
const RAIN = '#4f7fb3'

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const year = app.config.weather || {}
  if (!year.high || !year.high.length) {
    throw new Error(year.error || 'No weather yet')
  }
  const f = year.fahrenheit
  const days = year.high.length
  const u = Math.min(W, H) / 100
  const pad = u * 5
  const portrait = H > W

  // Areas: the title, the temperature chart, the months, the rain.
  const titleSize = u * (portrait ? 6 : 6.4)
  const label = u * (portrait ? 2.9 : 2.8)
  const left = pad + label * 2.4
  const right = W - pad
  const chartTop = pad + titleSize * 1.9
  const rainHeight = (H - chartTop) * 0.2
  const chartBottom = H - pad - rainHeight - label * 3.2
  const rainTop = chartBottom + label * 2.6
  const rainBottom = H - pad - label * 1.2
  const step = (right - left) / days
  const x = (i: number) => left + i * step

  // The temperature axis, in steps of 5 (or 10 °F).
  const values = year.high.concat(year.low).filter((v: number | null) => v != null)
  const tick = f ? 10 : 5
  const lowest = Math.floor(Math.min(...values) / tick) * tick
  const highest = Math.ceil(Math.max(...values) / tick) * tick
  const y = (t: number) => chartBottom - ((t - lowest) / (highest - lowest)) * (chartBottom - chartTop)

  const grid = []
  for (let t = lowest; t <= highest; t += tick) {
    grid.push(<line x1={left} y1={y(t)} x2={right} y2={y(t)} stroke={t === 0 && !f ? '#c9c0b3' : GRID} strokeWidth={u * (t === 0 && !f ? 0.3 : 0.18)} />)
    grid.push(
      <text x={left - label * 0.5} y={y(t) + label * 0.35} fontFamily="FiraGO" fontSize={label} fill={SOFT} textAnchor="end">
        {degrees(t)}
      </text>,
    )
  }

  // Months: a line where each starts, its name between, and its rain.
  const months = []
  const monthRain: { from: number; to: number; total: number; month: number }[] = []
  for (let i = 0; i < days; i++) {
    const date = new Date(year.start + i * 86400000)
    if (i === 0 || date.getUTCDate() === 1) {
      monthRain.push({ from: i, to: i, total: 0, month: date.getUTCMonth() })
    }
    const current = monthRain[monthRain.length - 1]
    current.to = i + 1
    current.total += year.rain[i] ?? 0
  }
  for (const m of monthRain) {
    const wide = m.to - m.from >= 12
    if (m.from > 0) months.push(<line x1={x(m.from)} y1={chartTop} x2={x(m.from)} y2={rainBottom} stroke={GRID} strokeWidth={u * 0.18} />)
    if (wide) {
      months.push(
        <text x={(x(m.from) + x(m.to)) / 2} y={chartBottom + label * 1.55} fontFamily="FiraGO" fontWeight={600} fontSize={label} fill={SOFT} textAnchor="middle">
          {MONTHS[m.month].substring(0, portrait ? 1 : 3).toUpperCase()}
        </text>,
      )
    }
  }

  // The days.
  const bars = []
  const barWidth = Math.max(1, step * 0.82)
  let warmest = -1
  let coldest = -1
  for (let i = 0; i < days; i++) {
    const hi = year.high[i]
    const lo = year.low[i]
    if (hi == null || lo == null) continue
    const ahead = i > year.today
    const color = temperatureColor(celsius((hi + lo) / 2, f))
    const top = y(hi)
    const height = Math.max(u * 0.4, y(lo) - top)
    if (ahead) {
      bars.push(<rect x={x(i) + step * 0.09} y={top} width={barWidth} height={height} fill={color} opacity={0.45} />)
    } else {
      bars.push(<rect x={x(i) + step * 0.09} y={top} width={barWidth} height={height} fill={color} />)
      if (warmest < 0 || hi > year.high[warmest]) warmest = i
      if (coldest < 0 || lo < year.low[coldest]) coldest = i
    }
  }

  const dateText = (i: number) => {
    const d = new Date(year.start + i * 86400000)
    return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()].substring(0, 3)}`
  }
  // A note beside a bar: on the side with room.
  const note = (i: number, atY: number, lines: string[], above: boolean) => {
    const toLeft = i > days * 0.7
    const nx = x(i) + (toLeft ? -label * 0.8 : label * 0.8) + step / 2
    const ny = atY + (above ? -label * 0.6 : label * 1.6)
    return (
      <g>
        <line x1={x(i) + step / 2} y1={atY} x2={nx} y2={ny - (above ? -label * 0.2 : label * 0.9)} stroke={INK} strokeWidth={u * 0.2} />
        {lines.map((text, k) => {
          const ty = ny + (above ? (k - lines.length + 1) * label * 1.15 : k * label * 1.15)
          // A halo of paper behind the words, so the bars do not run through them.
          return (
            <g>
              <text x={nx} y={ty} fontFamily="FiraGO" fontWeight={k === 0 ? 600 : 400} fontSize={label} fill={PAPER} stroke={PAPER} strokeWidth={label * 0.4} strokeLinejoin="round" textAnchor={toLeft ? 'end' : 'start'}>
                {text}
              </text>
              <text x={nx} y={ty} fontFamily="FiraGO" fontWeight={k === 0 ? 600 : 400} fontSize={label} fill={k === 0 ? INK : SOFT} textAnchor={toLeft ? 'end' : 'start'}>
                {text}
              </text>
            </g>
          )
        })}
      </g>
    )
  }

  // The rain, month by month.
  const rainMax = Math.max(1, ...monthRain.map((m) => m.total))
  const rainBars = monthRain.map((m) => {
    const height = ((rainBottom - rainTop - label * 1.3) * m.total) / rainMax
    const x0 = x(m.from) + step * 2
    const x1 = x(m.to) - step * 2
    const total = year.units.precipitation === 'in' ? m.total.toFixed(1) : Math.round(m.total)
    return (
      <g>
        <rect x={x0} y={rainBottom - height} width={Math.max(1, x1 - x0)} height={height} fill={RAIN} opacity={m.to - 1 > year.today ? 0.5 : 1} />
        {m.to - m.from >= 12 ? (
          <text x={(x0 + x1) / 2} y={rainBottom - height - label * 0.35} fontFamily="FiraGO" fontSize={label * 0.95} fill={SOFT} textAnchor="middle">
            {total}
          </text>
        ) : null}
      </g>
    )
  })
  let yearRain = 0
  for (let i = 0; i <= year.today && i < days; i++) yearRain += year.rain[i] ?? 0

  if (context.round === true) {
    return roundYear(W, H, year, days, monthRain, warmest, coldest, yearRain)
  }

  const todayX = x(year.today) + step / 2
  const title = `A year of weather in ${year.place || 'town'}`
  const subtitle = 'Daily high and low · the week ahead in pale'
  const fitsSubtitle = pad + title.length * titleSize * 0.85 * 0.56 + subtitle.length * label * 0.52 + u * 4 < right
  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <rect width={W} height={H} fill={PAPER} />
      <text x={pad} y={pad + titleSize * 0.8} fontFamily="FiraGO" fontWeight={600} fontSize={titleSize * 0.85} fill={INK}>
        {title}
      </text>
      <text x={right} y={pad + titleSize * 0.8} fontFamily="FiraGO" fontSize={label} fill={SOFT} textAnchor="end">
        {fitsSubtitle ? subtitle : ''}
      </text>
      {grid}
      {months}
      <line x1={todayX} y1={chartTop - label * 0.4} x2={todayX} y2={chartBottom} stroke={INK} strokeWidth={u * 0.25} />
      <text x={todayX} y={chartTop - label * 0.8} fontFamily="FiraGO" fontWeight={600} fontSize={label} fill={INK} textAnchor="middle">
        Today
      </text>
      {bars}
      {warmest >= 0 ? note(warmest, y(year.high[warmest]), [`Warmest ${degrees(year.high[warmest])}`, dateText(warmest)], false) : null}
      {coldest >= 0 ? note(coldest, y(year.low[coldest]), [`Coldest ${degrees(year.low[coldest])}`, dateText(coldest)], true) : null}
      <text x={left - label * 0.5} y={rainTop + label * 0.4} fontFamily="FiraGO" fontWeight={600} fontSize={label} fill={RAIN} textAnchor="end">
        Rain
      </text>
      <text x={left - label * 0.5} y={rainTop + label * 1.6} fontFamily="FiraGO" fontSize={label * 0.9} fill={SOFT} textAnchor="end">
        {year.units.precipitation}
      </text>
      {rainBars}
      <line x1={left} y1={rainBottom} x2={right} y2={rainBottom} stroke={INK} strokeWidth={u * 0.2} />
      <text x={right} y={H - pad * 0.6} fontFamily="FiraGO" fontSize={label} fill={SOFT} textAnchor="end">
        {`${year.units.precipitation === 'in' ? yearRain.toFixed(1) : Math.round(yearRain)} ${year.units.precipitation} of rain in twelve months · Open-Meteo`}
      </text>
    </svg>
  )
}

// A round panel shows only the circle inside its square: the year goes round
// it, today at the top and the months clockwise from a year ago, each day a
// spoke from its low to its high, the rain month by month in a ring inside,
// and the place and its extremes in the middle (docs/scene-guide.md).
function roundYear(W: number, H: number, year: any, days: number, monthRain: { from: number; to: number; total: number; month: number }[], warmest: number, coldest: number, yearRain: number) {
  const f = year.fahrenheit
  const cx = W / 2
  const cy = H / 2
  const r = Math.min(W, H) / 2
  const u = r / 50
  const label = Math.max(14, Math.round(r * 0.062))
  // A day's angle in turns: today at the top, the year before it clockwise.
  const turn = (i: number) => (i - year.today) / days
  const at = (radius: number, t: number) => [cx + Math.sin(t * Math.PI * 2) * radius, cy - Math.cos(t * Math.PI * 2) * radius]
  const f1 = (n: number) => n.toFixed(1)

  const values = year.high.concat(year.low).filter((v: number | null) => v != null)
  const tick = f ? 10 : 5
  const lowest = Math.floor(Math.min(...values) / tick) * tick
  const highest = Math.ceil(Math.max(...values) / tick) * tick
  const inner = r * 0.47
  const outer = r * 0.8
  const radiusOf = (t: number) => inner + ((t - lowest) / (highest - lowest)) * (outer - inner)

  const rings = []
  for (let t = lowest; t <= highest; t += tick) {
    rings.push(<circle cx={cx} cy={cy} r={radiusOf(t)} fill="none" stroke={t === 0 && !f ? '#c9c0b3' : GRID} strokeWidth={u * (t === 0 && !f ? 0.35 : 0.2)} />)
  }
  // The scale down the bottom, on a halo of paper.
  const scale = []
  for (let t = lowest; t <= highest; t += tick * 2) {
    const y = cy + radiusOf(t) + label * 0.35
    scale.push(
      <text x={cx} y={y} fontFamily="FiraGO" fontSize={label * 0.9} fill={PAPER} stroke={PAPER} strokeWidth={label * 0.35} strokeLinejoin="round" textAnchor="middle">
        {degrees(t)}
      </text>,
    )
    scale.push(
      <text x={cx} y={y} fontFamily="FiraGO" fontSize={label * 0.9} fill={SOFT} textAnchor="middle">
        {degrees(t)}
      </text>,
    )
  }

  const spokes = []
  const width = Math.max(1, ((Math.PI * 2 * (inner + outer)) / 2 / days) * 0.8)
  for (let i = 0; i < days; i++) {
    const hi = year.high[i]
    const lo = year.low[i]
    if (hi == null || lo == null) continue
    const [x1, y1] = at(radiusOf(lo), turn(i + 0.5))
    const [x2, y2] = at(Math.max(radiusOf(hi), radiusOf(lo) + u * 0.4), turn(i + 0.5))
    spokes.push(
      <line x1={f1(x1)} y1={f1(y1)} x2={f1(x2)} y2={f1(y2)} stroke={temperatureColor(celsius((hi + lo) / 2, f))} strokeWidth={width} opacity={i > year.today ? 0.45 : 1} />,
    )
  }

  // Months: a spoke where each starts, its name outside the ring.
  const rainInner = r * 0.36
  const rainOuter = r * 0.44
  const rainMax = Math.max(1, ...monthRain.map((m) => m.total))
  const months = []
  const rain = []
  for (const m of monthRain) {
    if (m.from > 0) {
      const [x1, y1] = at(rainInner, turn(m.from))
      const [x2, y2] = at(outer + u * 1.5, turn(m.from))
      months.push(<line x1={f1(x1)} y1={f1(y1)} x2={f1(x2)} y2={f1(y2)} stroke={GRID} strokeWidth={u * 0.2} />)
    }
    if (m.to - m.from >= 12) {
      const [lx, ly] = at(r * 0.885, turn((m.from + m.to) / 2))
      months.push(
        <text x={f1(lx)} y={f1(ly + label * 0.35)} fontFamily="FiraGO" fontWeight={600} fontSize={label} fill={SOFT} textAnchor="middle">
          {MONTHS[m.month].substring(0, 3).toUpperCase()}
        </text>,
      )
    }
    // The month's rain, a sector growing outward from the ring's inside.
    const from = turn(m.from) + 0.004
    const to = turn(m.to) - 0.004
    if (to > from && m.total > 0) {
      const reach = rainInner + ((rainOuter - rainInner) * m.total) / rainMax
      const [ax, ay] = at(reach, from)
      const [bx, by] = at(reach, to)
      const [cx2, cy2] = at(rainInner, to)
      const [dx, dy] = at(rainInner, from)
      rain.push(
        <path
          d={`M${f1(ax)} ${f1(ay)} A${f1(reach)} ${f1(reach)} 0 0 1 ${f1(bx)} ${f1(by)} L${f1(cx2)} ${f1(cy2)} A${f1(rainInner)} ${f1(rainInner)} 0 0 0 ${f1(dx)} ${f1(dy)} Z`}
          fill={RAIN}
          opacity={m.to - 1 > year.today ? 0.5 : 1}
        />,
      )
    }
  }

  const dot = (i: number, t: number) => {
    const [x, y] = at(radiusOf(t), turn(i + 0.5))
    return <circle cx={f1(x)} cy={f1(y)} r={u * 1.1} fill={PAPER} stroke={INK} strokeWidth={u * 0.4} />
  }
  const [tx1, ty1] = at(rainInner, 0)
  const [tx2, ty2] = at(outer + u * 0.8, 0)
  const total = `${year.units.precipitation === 'in' ? yearRain.toFixed(1) : Math.round(yearRain)} ${year.units.precipitation} of rain`
  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <rect width={W} height={H} fill={PAPER} />
      {rings}
      {months}
      {rain}
      {spokes}
      <line x1={tx1} y1={ty1} x2={tx2} y2={ty2} stroke={INK} strokeWidth={u * 0.4} />
      {warmest >= 0 ? dot(warmest, year.high[warmest]) : null}
      {coldest >= 0 ? dot(coldest, year.low[coldest]) : null}
      {scale}
      <text x={cx} y={cy - label * 1.55} fontFamily="FiraGO" fontWeight={600} fontSize={label * 1.15} fill={INK} textAnchor="middle">
        {year.place || 'A year'}
      </text>
      <text x={cx} y={cy - label * 0.3} fontFamily="FiraGO" fontSize={label} fill={INK} textAnchor="middle">
        {warmest >= 0 ? `Warmest ${degrees(year.high[warmest])}` : ''}
      </text>
      <text x={cx} y={cy + label * 0.95} fontFamily="FiraGO" fontSize={label} fill={INK} textAnchor="middle">
        {coldest >= 0 ? `Coldest ${degrees(year.low[coldest])}` : ''}
      </text>
      <text x={cx} y={cy + label * 2.2} fontFamily="FiraGO" fontSize={label * 0.9} fill={RAIN} textAnchor="middle">
        {total}
      </text>
    </svg>
  )
}

